FAMILIES = {
 'A': '소진되는 세계·시간·자원', 'B': '폐허의 거주·회수·재사용',
 'C': '생태·낯선 몸·돌봄의 접점', 'D': '환대·식사·수선·친밀함',
 'E': '공유자원·노동·도시 제도', 'F': '의례·계약·오컬트의 생활화',
 'G': '생활 속 불가해함·비교 단서', 'H': '애도·금기·비평·주장 경계',
}

def cards():
    result = []
    for line in DATA.strip().splitlines():
        fields = line.split('|')
        assert len(fields) == 12, (fields[0],len(fields))
        cid,title,seeds,slots,sources,mode,owners,edges,ko,en,confusion,limit = fields
        owner_map = dict(item.split(':',1) for item in owners.split(';'))
        relations = [dict(zip(('from','predicate','to'),edge.split('>'))) for edge in edges.split(';')]
        is_context = mode == 'context'
        result.append({
          'card_id':cid,'family':FAMILIES[cid[0]],'title_ko':title,
          'seed_ids':[int(x) for x in seeds.split(',')], 'proposed_slots':slots.split(','),
          'source_ids':sources.split(','),'observability':mode,
          'owners':{} if is_context else owner_map,'directed_relations':[] if is_context else relations,
          'context_scope':list(owner_map.values())[0] if is_context else None,
          'proposal_ko':ko,'proposal_en':en,'nearest_confusion_ko':confusion,
          'claim_limit_ko':limit,
          'priority':'P2' if is_context else ('P0' if int(cid[1:])<=8 else 'P1'),
          'adoption_mode':'context_only_no_positive_draft' if is_context else 'optional_complete_realization',
          'source_support':'meaning/context/analogy only; concrete geometry independently authored',
          'activation':'genre label never activates this card; explicit compatible post-core selection only',
          'native_approval':False,'requester_judgment':'not_yet_received',
          'gates':[] if is_context else [
            {'gate_id':f'{cid}-R{i+1}','required_relation':r,'both_endpoints_required':True,
             'partial_is_fail':True,'unobservable_is_pass':False,'pixel_status':'NOT_RUN'}
            for i,r in enumerate(relations)],
          'language_review':'authored bilingual draft; independent translator review pending',
        })
    return result
